define([], function() {
    return {
        init: function() {
            var scormIframe = document.getElementById('scorm_iframe');
            var scormLoader = document.getElementById('scorm_loader');
            var btnPrev = document.getElementById('scorm-btn-prev');
            var btnNext = document.getElementById('scorm-btn-next');
            var btnToggle = document.getElementById('btn-toggle-sidebar');
            var sidebar = document.getElementById('scorm-sidebar');
            var btnFullscreen = document.getElementById('btn-fullscreen');
            var container = document.getElementById('scorm-container');

            if (!scormIframe) return;

            // 1. Sidebar Toggle
            if (btnToggle && sidebar) {
                btnToggle.addEventListener('click', function() {
                    sidebar.classList.toggle('open');
                });
            }

            // 2. Fullscreen
            if (btnFullscreen && container) {
                btnFullscreen.addEventListener('click', function() {
                    if (!document.fullscreenElement) {
                        container.requestFullscreen().catch(function(err) {
                            console.log("Error attempting to enable fullscreen: " + err.message);
                        });
                        btnFullscreen.innerHTML = '<i class="fa fa-compress"></i>';
                    } else {
                        document.exitFullscreen();
                        btnFullscreen.innerHTML = '<i class="fa fa-expand"></i>';
                    }
                });
            }

            // 3. TOC Navigation
            var tocItems = Array.from(document.querySelectorAll('.scorm-toc-item'));
            
            function updateNavButtons() {
                if (!btnPrev || !btnNext) return;
                
                var currentIndex = tocItems.findIndex(function(item) {
                    return item.classList.contains('active');
                });

                btnPrev.disabled = (currentIndex <= 0);
                btnNext.disabled = (currentIndex >= tocItems.length - 1 || currentIndex === -1);
            }

            tocItems.forEach(function(item) {
                item.addEventListener('click', function(e) {
                    e.preventDefault();
                    var url = this.getAttribute('data-url');
                    
                    // Update active state in sidebar
                    tocItems.forEach(function(el) { el.classList.remove('active'); });
                    this.classList.add('active');

                    // Update buttons
                    updateNavButtons();

                    // Show loader and navigate
                    scormIframe.style.opacity = '0';
                    if (scormLoader) scormLoader.style.display = 'flex';
                    scormIframe.src = url;

                    if (window.innerWidth <= 768 && sidebar) {
                        sidebar.classList.remove('open');
                    }
                });
            });

            // Initial button setup
            updateNavButtons();

            // 4. Custom Next/Prev Buttons
            if (btnPrev) {
                btnPrev.addEventListener('click', function() {
                    var currentIndex = tocItems.findIndex(function(item) {
                        return item.classList.contains('active');
                    });
                    if (currentIndex > 0) {
                        tocItems[currentIndex - 1].click();
                    }
                });
            }

            if (btnNext) {
                btnNext.addEventListener('click', function() {
                    var currentIndex = tocItems.findIndex(function(item) {
                        return item.classList.contains('active');
                    });
                    if (currentIndex !== -1 && currentIndex < tocItems.length - 1) {
                        tocItems[currentIndex + 1].click();
                    }
                });
            }

            // 5. Iframe Load Handler
            scormIframe.addEventListener('load', function() {
                try {
                    var iframeDoc = scormIframe.contentDocument || scormIframe.contentWindow.document;
                    if (!iframeDoc) return;

                    // Safely hide Moodle UI without removing elements from layout flow completely 
                    // (prevents SCORM player JS math errors)
                    var style = iframeDoc.createElement('style');
                    style.innerHTML = `
                        #scorm_layout,
                        #scormmode,
                        header,
                        nav,
                        .page-header,
                        #page-header,
                        .secondary-navigation,
                        .tertiary-navigation,
                        #scormnav,
                        #scorm_navpanel,
                        #scorm_toc_toggle,
                        #tocbox {
                            position: absolute !important;
                            top: -9999px !important;
                            left: -9999px !important;
                            width: 1px !important;
                            height: 1px !important;
                            overflow: hidden !important;
                            visibility: hidden !important;
                            opacity: 0 !important;
                        }
                        
                        /* Normalize layout */
                        body, html {
                            margin: 0 !important;
                            padding: 0 !important;
                            background: transparent !important;
                            overflow: hidden !important;
                            width: 100% !important;
                            height: 100% !important;
                        }
                        
                        #page, #page-content, #region-main-box, #region-main, #scormtop, #scormpage, #scormcontent {
                            padding: 0 !important;
                            margin: 0 !important;
                            width: 100vw !important;
                            height: 100vh !important;
                            max-width: none !important;
                            border: none !important;
                            background: transparent !important;
                        }
                        
                        /* Ensure the actual content object takes full height */
                        #scorm_object {
                            width: 100vw !important;
                            height: 100vh !important;
                            border: none !important;
                            display: block !important;
                        }
                    `;
                    iframeDoc.head.appendChild(style);

                    // Reveal iframe
                    if (scormLoader) scormLoader.style.display = 'none';
                    scormIframe.style.opacity = '1';

                } catch (e) {
                    console.log("Cross-origin restriction or error modifying iframe: ", e);
                    // Reveal anyway if CORS prevents modification
                    if (scormLoader) scormLoader.style.display = 'none';
                    scormIframe.style.opacity = '1';
                }
            });
        }
    };
});